259	#ifdef SG_DEC_PROFILE
260	// Diagnostic-only (SG_DEC_PROFILE; never shipped — the production _ops never sets
261	// this flag). Read + reset the per-phase clock64 maxima (cycles), 8 slots:
262	// [0]=P1 fwd, [1]=P1 bwd, [2]=B1 wait, [3]=P2 dW-GEMM, [4]=P2 grad-assembly,
263	// [5]=P3 opt tail, [6]=B2 wait, [7]=B0 wait. Call AFTER one tc_train_step; divide
264	// by the SM clock (~1.99 GHz boost on H100) to get ms, or read the RATIOS.
265	static std::vector<int64_t> tc_profile_read() {
266	    unsigned long long h[8] = {0, 0, 0, 0, 0, 0, 0, 0};
267	    cudaMemcpyFromSymbol(h, ::sg::fused::sm90::g_dec_prof_max, sizeof(h));
268	    unsigned long long z[8] = {0, 0, 0, 0, 0, 0, 0, 0};
269	    cudaMemcpyToSymbol(::sg::fused::sm90::g_dec_prof_max, z, sizeof(z));
270	    std::vector<int64_t> out(8);
271	    for (int i = 0; i < 8; ++i) out[i] = (int64_t)h[i];
272	    return out;
273	}
