41	// ════════════════════════════════════════════════════════════════════════════
42	//  PART 1 — GEMM-orientation micro-gates (the SAME engine the decoder selftest
43	//  silicon-gated 13/13; the engine is model-agnostic, but exercising it through
44	//  a ViT TU at the ViT TILE_M=1088 (17 stacked m64 atoms) is the honest witness
45	//  for the ViT path's M-atom stacking). Three orientations: fwd / dX / dW, each
46	//  one tiny GEMM on a single CTA (256 thr) returning the fp32 result. ──────────
47	// ════════════════════════════════════════════════════════════════════════════
48	
49	// Ring smem: kVitAtomsPerSlot A(64×16) tiles [the M-atom interleave group] + one
50	// B(N=128×16) tile. Without the kVitAtomsPerSlot factor the interleaved engine
51	// stages the group's 2nd A-tile out of bounds (illegal access).
52	static size_t arena_bytes() {
53	    return (size_t)(vittc::kVitAtomsPerSlot * 64 * 16 + 128 * 16) * sizeof(__nv_bfloat16) + 256;
54	}
55	
56	// (fwd) Y[M,Nout] = X[M,Kin] @ W[Nout,Kin]^T. M = TILE_M (17 atoms). N-tiled.
57	template <int N>
58	__global__ void __launch_bounds__(256)
59	gemm_fwd_kernel(const __nv_bfloat16* __restrict__ X, const __nv_bfloat16* __restrict__ W,
60	                float* __restrict__ D, int Kin, int Nout) {
61	#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 900)
62	    extern __shared__ __nv_bfloat16 smem[];
63	    __nv_bfloat16* sA = smem; __nv_bfloat16* sB = sA + vittc::kVitAtomsPerSlot * 64 * 16;
64	    const int M = vittc::kTileM, m_atoms = M / 64, k_steps = Kin / 16;
65	    for (int n0 = 0; n0 < Nout; n0 += N) {
66	        const int n_real = (Nout - n0) < N ? (Nout - n0) : N;
67	        auto srcA = [&] (int m, int k) -> __nv_bfloat16 { return X[(int64_t)m * Kin + k]; };
68	        auto srcB = [&] (int n, int k) -> __nv_bfloat16 {
69	            int nn = n0 + n; return nn < Nout ? W[(int64_t)nn * Kin + k] : __float2bfloat16(0.f); };
70	        auto out  = [&] (int m, int n, float v) { if (m < M) D[(int64_t)m * Nout + n0 + n] = v; };
71	        // The micro-gate exercises full tiles (M=kTileM=17·64, no pad) and self-
72	        // guards `out` with m<M, so the engine's m_real row-guard (present only
73	        // when the P1 sub-tile knob is ON) is a no-op here. SG_VIT_DW_MREAL_ARG
74	        // expands to nothing when the knob is OFF (byte-identical) and to a
75	        // no-op upper bound when ON (so the TU still compiles at S<64).
76	        vittc::tc_gemm_block_unpipelined<N, /*MaxAtomsM=*/vittc::kAtomsM>(
77	            0, m_atoms, n_real, k_steps SG_VIT_DW_MREAL_ARG, srcA, srcB, out, sA, sB);
78	    }
79	#else
80	    (void)X; (void)W; (void)D; (void)Kin; (void)Nout;
81	#endif
82	}
83	
84	// (dX) dX[m,kin] = Σ_out dY[m,out]·W[out,kin]. N(wgmma)=Kin, K=Nout, W transposed.
85	template <int N>
86	__global__ void __launch_bounds__(256)
87	gemm_dx_kernel(const __nv_bfloat16* __restrict__ dY, const __nv_bfloat16* __restrict__ W,
88	               float* __restrict__ dX, int Nout) {
89	#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 900)
90	    extern __shared__ __nv_bfloat16 smem[];
91	    __nv_bfloat16* sA = smem; __nv_bfloat16* sB = sA + vittc::kVitAtomsPerSlot * 64 * 16;
92	    const int M = vittc::kTileM, m_atoms = M / 64, k_steps = Nout / 16;
93	    auto srcA = [&] (int m, int k) -> __nv_bfloat16 { return dY[(int64_t)m * Nout + k]; };
94	    auto srcB = [&] (int n, int k) -> __nv_bfloat16 { return W[(int64_t)k * N + n]; };
95	    auto out  = [&] (int m, int n, float v) { if (m < M) dX[(int64_t)m * N + n] = v; };
96	    vittc::tc_gemm_block_unpipelined<N, /*MaxAtomsM=*/vittc::kAtomsM>(
97	        0, m_atoms, /*n_real=*/N, k_steps SG_VIT_DW_MREAL_ARG, srcA, srcB, out, sA, sB);
98	#else
99	    (void)dY; (void)W; (void)dX; (void)Nout;
100	#endif
101	}
102	
103	// (dW) dW[out,in] = Σ_t dY[t,out]·X[t,in]. BOTH transposed, K=T multi-k-step.
104	template <int N>
105	__global__ void __launch_bounds__(256)
106	gemm_dw_kernel(const __nv_bfloat16* __restrict__ dY, const __nv_bfloat16* __restrict__ X,
107	               float* __restrict__ dW, int Nout, int T) {
108	#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 900)
109	    extern __shared__ __nv_bfloat16 smem[];
110	    __nv_bfloat16* sA = smem; __nv_bfloat16* sB = sA + vittc::kVitAtomsPerSlot * 64 * 16;
111	    const int k_steps = T / 16, m_atoms = (Nout + 63) / 64;   // up to 8 for Nout=512
112	    auto srcA = [&] (int m, int k) -> __nv_bfloat16 {
113	        return m < Nout ? dY[(int64_t)k * Nout + m] : __float2bfloat16(0.f); };
114	    auto srcB = [&] (int n, int k) -> __nv_bfloat16 { return X[(int64_t)k * N + n]; };
115	    auto out  = [&] (int m, int n, float v) { if (m < Nout) dW[(int64_t)m * N + n] = v; };
116	    vittc::tc_gemm_block_unpipelined<N, /*MaxAtomsM=*/8>(
117	        0, m_atoms, /*n_real=*/N, k_steps SG_VIT_DW_MREAL_ARG, srcA, srcB, out, sA, sB);
118	#else
119	    (void)dY; (void)X; (void)dW; (void)Nout; (void)T;
120	#endif
121	}
