175	// ════════════════════════════════════════════════════════════════════════════
176	//  PART 2 — full-cell driver. One persistent set of barrier/queue counters + the
177	//  TC workspace, cached per device. Re-created if a larger B requires a larger
178	//  workspace.
179	// ════════════════════════════════════════════════════════════════════════════
180	struct TcScratch {
181	    torch::Tensor g_next, g_arrived, g_generation, workspace;
182	    int n_ctas = 0;
183	    int64_t ws_floats = 0;
184	};
185	
186	static int tc_effective_nctas(const torch::Tensor& params, int ncta_cap) {
187	    int dev = params.get_device();
188	    int n_sms = 1;
189	    cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
190	    int n = n_sms;
191	    if (ncta_cap > 0 && ncta_cap < n) n = ncta_cap;
192	    return n;
193	}
194	
195	static TcScratch& tc_scratch_for(const torch::Tensor& params, int B, int nCTA) {
196	    static TcScratch s;
197	    const int T = B * vit::kSeq;
198	    const int64_t need = ::sg::fused::sm90::vit_tc_workspace_floats(T, B, nCTA);
199	    if (!s.g_next.defined()) {
200	        auto opt_i = torch::dtype(torch::kInt32).device(params.device());
201	        s.g_next = torch::zeros({1}, opt_i);
202	        s.g_arrived = torch::zeros({1}, opt_i);
203	        s.g_generation = torch::zeros({1}, opt_i);
204	    }
205	    s.n_ctas = nCTA;
206	    if (s.ws_floats < need) {
207	        auto opt_f = torch::dtype(torch::kFloat32).device(params.device());
208	        s.workspace = torch::empty({need}, opt_f);
209	        s.ws_floats = need;
210	    }
211	    return s;
212	}
213	
214	// tc_train_step: one Fork-B TC step. params [total] fp32 (updated in place);
215	// patches [B, kNPatch, kPatch] fp32; targets [B] int32; state [3*total] fp32.
216	// Returns {loss (cpu float scalar), grad [total] fp32 (the reduced grad)}.
217	static std::vector<torch::Tensor> tc_train_step(
218	        torch::Tensor params, torch::Tensor patches, torch::Tensor targets,
219	        torch::Tensor state, double lr, double beta1, double beta2, double eps,
220	        double weight_decay, double bc1, double bc2, int64_t step,
221	        int64_t ncta_cap) {
222	    TORCH_CHECK(params.is_cuda() && params.scalar_type() == torch::kFloat32 && params.is_contiguous());
223	    TORCH_CHECK(params.numel() == kVitTotalElems, "params must be the flat ViT blob (", kVitTotalElems, ")");
224	    TORCH_CHECK(patches.is_cuda() && patches.scalar_type() == torch::kFloat32 && patches.is_contiguous());
225	    TORCH_CHECK(targets.is_cuda() && targets.scalar_type() == torch::kInt32 && targets.is_contiguous());
226	    const int B = (int)targets.numel();
227	    TORCH_CHECK(patches.numel() == (int64_t)B * vit::kNPatch * vit::kPatch,
228	                "patches must be [B, kNPatch, kPatch]");
229	    TORCH_CHECK((B % 16) == 0, "TC path requires B %% 16 == 0 (dW K-loop is 16-step atoms)");
230	    const int64_t total = kVitTotalElems;
231	    TORCH_CHECK(state.is_cuda() && state.scalar_type() == torch::kFloat32 && state.is_contiguous()
232	                && state.numel() >= 3 * total, "state must be contiguous fp32 [>=3*total]");
233	
234	    const int nCTA = tc_effective_nctas(params, (int)ncta_cap);
235	    TcScratch& sc = tc_scratch_for(params, B, nCTA);
236	    auto grad = torch::zeros({total}, torch::dtype(torch::kFloat32).device(params.device()));
237	    auto loss_dev = torch::zeros({1}, torch::dtype(torch::kFloat32).device(params.device()));
238	
239	    PersistentContext ctx{
240	        sc.g_next.data_ptr<int>(),
241	        reinterpret_cast<unsigned*>(sc.g_arrived.data_ptr<int>()),
242	        reinterpret_cast<unsigned*>(sc.g_generation.data_ptr<int>()),
243	        kVitNumTensors,
244	        0u};
245	
246	    FusedOptState st;
247	    float* m = state.data_ptr<float>();
248	    st.exp_avg = m;
249	    st.exp_avg_sq = m + total;
250	    st.lr = (float)lr; st.beta1 = (float)beta1; st.beta2 = (float)beta2;
251	    st.eps = (float)eps; st.wd = (float)weight_decay;
252	    st.bc1 = (float)bc1; st.bc2 = (float)bc2;
253	
254	    ViTInputCtx in;
255	    in.patches = patches.data_ptr<float>();
256	    in.targets = targets.data_ptr<int>();
257	    in.B = B;
258	    in.workspace = sc.workspace.data_ptr<float>();
259	    in.loss_out = loss_dev.data_ptr<float>();
260	
261	    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
262	    cudaError_t err = ::sg::fused::sm90::launch_fused_vit_megakernel_tc<OptId::AdamW>(
263	        ctx, params.data_ptr<float>(), in, grad.data_ptr<float>(),
264	        (float)lr, (int)step, st, stream, nCTA);
265	    TORCH_CHECK(err == cudaSuccess, "TC megakernel launch failed: ", cudaGetErrorString(err));
266	    C10_CUDA_CHECK(cudaStreamSynchronize(stream));
267	
268	    return {loss_dev.to(torch::kCPU), grad};
269	}
270	
271	// CALIBRATION HOOK (test_vit_tc.py::test_tc_dw_gemm_exact_on_own_operands): slice
272	// the kernel's OWN stored bf16 acts dY_ff2[L1] [T,d] and X_gact[L1] [T,dff] from
273	// the workspace, returned as fp32 CPU tensors. The gate contracts them in fp32
274	// ascending-t and compares to the kernel's ff2.weight grad slice — isolating the
275	// dW GEMM (incl. the ONLY Kin=dff multi-N-tile path) from operand-chain bf16
276	// divergence. Re-uses the cached workspace from the last tc_train_step.
277	static std::vector<torch::Tensor> tc_dump_ff2_operands(torch::Tensor params, int64_t B) {
278	    TcScratch& sc = tc_scratch_for(params, (int)B, tc_effective_nctas(params, 4));
279	    const int T = (int)B * vit::kSeq;
280	    const int64_t d = vit::kD, dff = vit::kDff;
281	    const int Tp = (int)B * vit::kNPatch;
282	    auto acts_bf16 = sc.workspace.slice(0, 0, ::sg::fused::sm90::vit_tc_acts_floats(T, (int)B))
283	                         .view(torch::kBFloat16);
284	    // mirror vit_acts_bind: walk to dY_ff2[1] and X_gact[1].
285	    const int64_t Td = (int64_t)T * d, T3d = (int64_t)T * 3 * d, Tff = (int64_t)T * dff;
286	    int64_t off = (int64_t)Tp * vit::kPatch;    // skip X_patch
287	    int64_t off_Xgact1 = -1, off_dYff2_1 = -1;
288	    for (int li = 0; li < vit::kLayers; ++li) {
289	        off += Td;          // X_in
290	        off += Td;          // X_ctx
291	        off += Td;          // X_x1
292	        if (li == 1) off_Xgact1 = off;
293	        off += Tff;         // X_gact
294	        off += T3d;         // dY_qkv
295	        off += Td;          // dY_a
296	        off += Tff;         // dY_ff0
297	        if (li == 1) off_dYff2_1 = off;
298	        off += Td;          // dY_ff2
299	    }
300	    auto Xgact1 = acts_bf16.slice(0, off_Xgact1, off_Xgact1 + Tff).to(torch::kFloat32).to(torch::kCPU);
301	    auto dYff2_1 = acts_bf16.slice(0, off_dYff2_1, off_dYff2_1 + Td).to(torch::kFloat32).to(torch::kCPU);
302	    return {dYff2_1, Xgact1};  // [T*d], [T*dff]
303	}
