42	// Persistent barrier/queue counters + the TC workspace, cached per device.
43	struct TcScratch {
44	    torch::Tensor g_next, g_arrived, g_generation, workspace;
45	    int n_ctas = 0;
46	    int64_t ws_floats = 0;
47	};
48	
49	static int tc_effective_nctas(const torch::Tensor& params, int ncta_cap) {
50	    int dev = params.get_device();
51	    // Use the EXACT count the launcher will run (occ·n_sms with occupancy-fill) so
52	    // the workspace (per-CTA scratch + partials = nCTA·slab) is sized for what runs.
53	    // occ is register-capped uniform across OptIds by __launch_bounds__(256,2), so
54	    // AdamW's count == every tail's count. Fall back to n_sms if the attr query fails.
55	    int n = ::sg::fused::sm90::mb_tc_launched_nctas<::sg::fused::sm90::OptId::AdamW>(dev, ncta_cap);
56	    if (n <= 0) {
57	        int n_sms = 1;
58	        cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
59	        n = n_sms;
60	        if (ncta_cap > 0 && ncta_cap < n) n = ncta_cap;
61	    }
62	    return n;
63	}
64	
65	static TcScratch& tc_scratch_for(const torch::Tensor& params, int B, int nCTA) {
66	    static TcScratch s;
67	    const int T = B * mb::kSeq;
68	    const int64_t need = ::sg::fused::sm90::mb_tc_workspace_floats(T, nCTA);
69	    if (!s.g_next.defined()) {
70	        auto opt_i = torch::dtype(torch::kInt32).device(params.device());
71	        s.g_next = torch::zeros({1}, opt_i);
72	        s.g_arrived = torch::zeros({1}, opt_i);
73	        s.g_generation = torch::zeros({1}, opt_i);
74	    }
75	    s.n_ctas = nCTA;
76	    if (s.ws_floats < need) {
77	        auto opt_f = torch::dtype(torch::kFloat32).device(params.device());
78	        s.workspace = torch::empty({need}, opt_f);
79	        s.ws_floats = need;
80	    }
81	    return s;
82	}
