218	    tok.tokens = tokens.data_ptr<int>();
219	    tok.targets = targets.data_ptr<int>();
220	    tok.B = B;
221	    tok.workspace = s_ws.data_ptr<float>();
222	    tok.loss_out = loss_out;
223	
224	    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
225	    cudaError_t err = ::sg::fused::sm90::launch_fused_mamba_megakernel<OptId::AdamW>(
